<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import AppIcon from '../../../../shared/components/layout/AppIcon.vue'
import { useGlobalSearch } from '../../../../shared/composables/useGlobalSearch'
import { useToast } from '../../../../shared/composables/useToast'
import { createTeamLoan, getLoanSummary, getTeamLoans, getTeamMembers, repayTeamLoan, voidTeamLoan } from '../api/teamLoans'
import TeamLoanModal from '../components/modal/TeamLoanModal.vue'
import TeamLoanList from '../components/list-data/TeamLoanList.vue'
import type { LoanPayload, LoanSummary, RepaymentPayload, TeamLoan, TeamMember } from '../types/teamLoan'
const { searchQuery } = useGlobalSearch(); const { showToast } = useToast(); const loans = ref<TeamLoan[]>([]); const members = ref<TeamMember[]>([]); const summary = ref<LoanSummary | null>(null)
const loading = ref(true); const submitting = ref(false); const page = ref(1); const lastPage = ref(1); const total = ref(0); const modalOpen = ref(false); const mode = ref<'create'|'repay'|'void'>('create'); const selected = ref<TeamLoan|null>(null); const error = ref(''); const loadError = ref(''); const notice = ref(''); const sentinel = ref<HTMLElement|null>(null)
const hasMore = computed(() => page.value < lastPage.value); let timer: ReturnType<typeof setTimeout>|undefined; let observer: IntersectionObserver|undefined; let sequence=0
async function load(requested=1, append=false) { if(append&&loading.value)return;const id=++sequence;loading.value=true;loadError.value='';try{const result=await getTeamLoans(searchQuery.value,requested);if(id!==sequence)return;loans.value=append?[...loans.value,...result.data]:result.data;page.value=result.current_page;lastPage.value=result.last_page;total.value=result.total}catch(e){if(id===sequence)loadError.value=e instanceof Error?e.message:'Daftar kasbon gagal dimuat.'}finally{if(id===sequence)loading.value=false} }
async function refresh(){await Promise.all([load(),getLoanSummary().then(x=>summary.value=x).catch(()=>{} )])}
watch(searchQuery,()=>{page.value=1;loans.value=[];lastPage.value=1;clearTimeout(timer);timer=setTimeout(()=>void load(),300)})
watch(sentinel,(el,prev)=>{if(prev)observer?.unobserve(prev);if(el)observer?.observe(el)},{flush:'post'})
onMounted(()=>{void refresh();void getTeamMembers().then(x=>members.value=x.data).catch(e=>loadError.value=e instanceof Error?e.message:'Daftar anggota gagal dimuat.');if('IntersectionObserver'in window)observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)&&hasMore.value&&!loading.value)void load(page.value+1,true)},{rootMargin:'240px 0px'});if(sentinel.value)observer?.observe(sentinel.value)})
onUnmounted(()=>{clearTimeout(timer);observer?.disconnect();sequence++})
function open(kind:'create'|'repay'|'void',loan:TeamLoan|null=null){mode.value=kind;selected.value=loan;error.value='';modalOpen.value=true}
async function saveLoan(payload:LoanPayload){submitting.value=true;error.value='';try{const loan=await createTeamLoan(payload);modalOpen.value=false;showToast(`Kasbon ${loan.code} berhasil dicatat.`);await refresh()}catch(e){error.value=e instanceof Error?e.message:'Kasbon gagal disimpan.';showToast(error.value,'error')}finally{submitting.value=false}}
async function saveRepayment(payload:RepaymentPayload){if(!selected.value)return;submitting.value=true;error.value='';try{const repayment=await repayTeamLoan(selected.value.id,payload);modalOpen.value=false;showToast(`Pembayaran ${repayment.code} berhasil dicatat.`);await refresh()}catch(e){error.value=e instanceof Error?e.message:'Pembayaran gagal disimpan.';showToast(error.value,'error')}finally{submitting.value=false}}
async function correctLoan(reason:string){if(!selected.value)return;submitting.value=true;error.value='';try{const loan=await voidTeamLoan(selected.value.id,reason);modalOpen.value=false;showToast(`Kasbon ${loan.code} dikoreksi dan riwayatnya tetap tersimpan.`);await refresh()}catch(e){error.value=e instanceof Error?e.message:'Koreksi kasbon gagal.';showToast(error.value,'error')}finally{submitting.value=false}}
const money=new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0})
</script>
<template><main class="page"><div class="content"><div class="breadcrumb"><span>Keuangan</span><AppIcon name="chevron-right" :size="13"/><strong>Kasbon Tim</strong></div><header class="heading"><div><span class="overline"><i/> KEUANGAN · PIUTANG TIM</span><h1>Kasbon Tim</h1><p>Catat kasbon dan pantau cicilan serta sisa per anggota.</p></div><button class="add" type="button" @click="open('create')"><AppIcon name="plus" :size="16"/><span>Catat kasbon</span></button></header>
<section v-if="summary" class="summary"><article><small>Saldo kas tersedia</small><strong>{{ money.format(Number(summary.cash_available)) }}</strong><span>Saldo awal Rp0; penerimaan menambah kas.</span></article><article><small>Total kasbon aktif</small><strong>{{ money.format(Number(summary.outstanding)) }}</strong><span>Sisa piutang yang belum dilunasi.</span></article><article><small>Kasbon dicairkan</small><strong>{{ money.format(Number(summary.loans_disbursed)) }}</strong><span>Pembayaran cicilan {{ money.format(Number(summary.repayments_received)) }}.</span></article></section>
<section v-if="summary?.borrower_balances?.length" class="borrowers"><h2>Sisa kasbon per anggota</h2><div><article v-for="person in summary.borrower_balances" :key="person.id"><span>{{ person.name }}<small v-if="person.username">@{{ person.username }}</small></span><strong>{{ money.format(Number(person.outstanding)) }}</strong></article></div></section>
<div class="toolbar"><div class="list-heading"><h2>Daftar kasbon</h2><span>{{ total }}</span></div><span class="search-hint"><AppIcon name="search" :size="14"/> Gunakan pencarian di bagian atas</span></div><div v-if="notice" class="notice" role="status">{{ notice }}<button type="button" @click="notice=''">Tutup</button></div><div v-if="loadError" class="error">{{ loadError }} <button type="button" @click="refresh">Coba lagi</button></div><section class="list"><TeamLoanList :loans="loans" :loading="loading&&!loans.length" @repay="open('repay',$event)" @void="open('void',$event)"/></section><div v-if="loans.length" ref="sentinel" class="scroll"> <span v-if="loading">Memuat kasbon berikutnya...</span><button v-else-if="hasMore" type="button" @click="load(page+1,true)">Muat berikutnya</button><span v-else>Semua {{ total }} kasbon ditampilkan</span></div></div><TeamLoanModal :open="modalOpen" :mode="mode" :loan="selected" :members="members" :submitting="submitting" :error="error" @close="modalOpen=false" @submit-loan="saveLoan" @submit-repayment="saveRepayment" @void-loan="correctLoan"/></main></template>
<style scoped>.page{min-height:calc(100vh - 64px);margin-left:76px;color:#eff1ed}.content{width:min(100%,1400px);margin:auto;padding:24px clamp(20px,3vw,48px) 45px}.breadcrumb{display:flex;align-items:center;gap:7px;color:#92988e;font-size:10px}.breadcrumb strong{color:#dce0d7}.heading{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin:24px 0 20px}.overline{display:flex;align-items:center;gap:7px;color:#a1a99a;font-size:9px;font-weight:700;letter-spacing:1px}.overline i{width:6px;height:6px;border-radius:50%;background:#ffd64c}.heading h1{margin:9px 0 5px;font:700 30px Manrope,sans-serif}.heading p{margin:0;color:#9da398;font-size:11px}.add{height:39px;display:flex;align-items:center;gap:8px;padding:0 14px;border:0;border-radius:8px;background:#ffd64c;color:#263215;font-size:11px;font-weight:700}.summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-bottom:20px}.summary article{display:grid;gap:9px;padding:14px;border:1px solid #ffffff12;border-radius:10px;background:#191b19}.summary small,.summary span{color:#92988e;font-size:9px}.summary strong{font:700 clamp(16px,2vw,21px) Manrope,sans-serif;overflow-wrap:anywhere}.borrowers{margin-bottom:20px}.borrowers h2{margin:0 0 9px;font:700 13px Manrope,sans-serif}.borrowers>div{display:flex;gap:8px;overflow:auto}.borrowers article{min-width:175px;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 12px;border:1px solid #ffffff12;border-radius:8px;background:#191b19}.borrowers article span{display:grid;gap:3px;color:#e3e7df;font-size:10px}.borrowers article small{color:#858c80;font-size:9px}.borrowers article strong{color:#f0d56a;font-size:10px;white-space:nowrap}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px}.list-heading{display:flex;align-items:center;gap:9px}.list-heading h2{margin:0;font:700 15px Manrope,sans-serif}.list-heading>span{padding:3px 7px;border-radius:12px;background:#ffffff0d;color:#b8c0b0;font-size:9px}.search-hint{display:flex;gap:6px;align-items:center;color:#8f968b;font-size:10px}.list{overflow:hidden;border:1px solid #ffffff12;border-radius:11px;background:#191b19}.scroll{min-height:43px;display:flex;align-items:center;justify-content:center;padding:12px;color:#92988e;font-size:10px}.scroll button,.notice button,.error button{border:0;background:transparent;color:#c7d99f}.notice,.error{margin-bottom:12px;padding:10px 12px;border-radius:8px;background:#8bd74f0b;color:#c5df9e;font-size:11px}.notice{display:flex;justify-content:space-between}.error{background:#a7463c18;color:#ffb4a8}@media(max-width:760px){.summary{grid-template-columns:repeat(2,minmax(0,1fr))}.summary article:last-child{grid-column:1/-1}}@media(max-width:600px){.page{min-height:calc(100vh - 58px);margin-left:0}.content{padding:18px 12px 32px}.heading{align-items:flex-start;margin:20px 0 18px}.heading h1{font-size:25px}.heading p{max-width:230px;line-height:1.5}.add{height:36px;padding:0 10px;font-size:0}.toolbar{align-items:flex-start;flex-direction:column}.search-hint{font-size:9px}.summary{gap:8px}.summary article{padding:11px}.borrowers>div{margin-right:-12px;padding-right:12px}}@media(max-width:360px){.summary{grid-template-columns:1fr}.summary article:last-child{grid-column:auto}}</style>
